def audit_chain(events):
    result=[]
    for event in events:
        serialized=json.dumps(event,sort_keys=True,separators=(",",":"),ensure_ascii=False)
        result.append(hashlib.sha256(("0"*64+"\n"+serialized).encode()).hexdigest())
